 "content": "from collections import deque


def transform(grid):
    """Recolor the largest zero component 8 and the smallest zero component 7."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            component = []
            while q:
                x, y = q.popleft()
                component.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0
                            and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            components.append(component)
    if components:
        largest = max(components, key=len)
        smallest = min(components, key=len)
        for r, c in largest:
            out[r][c] = 8
        for r, c in smallest:
            out[r][c] = 7
    return out
